Add({
	kind = "topic",
	id = "cult-of-the-dark-strand",
	title = "Cult of the Dark Strand",
	aliases = { "Dark Strand" },
	category = "group",
	region = "darkshore",
	unlock = {
		{ type = "quest", id = 966 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Cult of the Dark Strand is a company of warlocks that has taken the {link:tower-of-althalaxx}Tower of Althalaxx{/link} in {link:darkshore}Darkshore{/link}. It had no name that the {link:sentinels}Sentinels{/link} knew until {link:balthule-shadowstrike}Balthule Shadowstrike{/link} pieced one together from scraps of its parchment. Its fanatics and voidcallers serve {link:athrikus-narassin}Athrikus Narassin{/link}, the ancient Highborne lord of the tower.]=],
		},
		{
			title = "Its Power",
			text = [=[The cult draws on soul gems. {link:athrikus-narassin}Athrikus{/link} kept the souls of Highborne trapped in them, and hid them in the {link:satyrs}satyr{/link} lands of northern {link:ashenvale}Ashenvale{/link}, at {link:night-run}Night Run{/link} and {link:satyrnaar}Satyrnaar{/link}. The cult also works at {link:the-ruins-of-ordil-aran}Ordil'Aran{/link} in Ashenvale. It has dealings with the {link:orcs}orc{/link} warlock {link:ilkrud-magthrull}Ilkrud Magthrull{/link} of the {link:fire-scar-shrine}Fire Scar Shrine{/link}, who kept notes on its plans. {link:delgren-the-purifier}Delgren the Purifier{/link} has made its end his task.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "blackwood-furbolgs",
	title = "Blackwood Furbolgs",
	aliases = { "Blackwood", "Blackwood tribe" },
	category = "group",
	region = "darkshore",
	unlock = {
		{ type = "quest", id = 984 },
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The Blackwood are a tribe of {link:furbolgs}furbolgs{/link} in {link:darkshore}Darkshore{/link}. They were friends of the night elves, and the elves still remember them so. Now they are corrupted. They live in camps along the {link:cliffspring-river}Cliffspring River{/link} in the north and in the south, and they attack any elf who comes near.]=],
		},
		{
			title = "The Corruption",
			text = [=[The elves of {link:auberdine}Auberdine{/link} have traced part of the Blackwood's madness to the satyrs. A {link:satyrs}satyr{/link} corruptor holds them through a talisman. When the furbolgs ate food mixed with moonwell water, they were cleansed for a short time. The elder of Auberdine hopes that one day they may be freed for good. Yet the deeper poison runs in the land and the water, and it comes from {link:felwood}Felwood{/link}.]=],
		},
	},
})
